//! include/hypercast.h, the C header, is generated by cbindgen (configured in cbindgen.toml)
//! from src/ffi.rs and the types its exports take, and the Swift artifact bundle carries a
//! byte-identical copy as its module's header. This regenerates it and fails when either
//! committed file differs, so a change to an export, a type it takes or a doc comment on
//! either cannot leave a header behind. `HYPERCAST_BLESS=1` writes both.
//!
//! Two places cannot check it, and every other leg does. wasm: cbindgen runs `cargo
//! metadata`, a subprocess wasmtime cannot start, so the test is compiled out. A copy of rust/
//! without the repository around it (the Forge's musl build takes only rust/ and corpus/ into
//! its container): the test says so and passes. Line endings are LF on every checkout,
//! Windows' included (.gitattributes), so the comparison is byte for byte.
#![cfg(not(target_family = "wasm"))]

use cbindgen::ir::{ItemContainer, Literal};
use std::path::Path;

const HEADERS: [&str; 2] =
    ["../include/hypercast.h", "../swift/HyperCastCore.artifactbundle/include/hypercast.h"];

#[test]
fn committed_headers_are_what_cbindgen_generates() {
    let crate_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let bless = std::env::var_os("HYPERCAST_BLESS").is_some();
    if !bless && !crate_dir.join("../include").is_dir() {
        eprintln!("skipped: no include/ beside rust/, so this is not a whole checkout");
        return;
    }
    let config = cbindgen::Config::from_file(crate_dir.join("cbindgen.toml")).unwrap();
    let mut bindings =
        cbindgen::Builder::new().with_crate(crate_dir).with_config(config).generate().unwrap();
    // An associated constant whose value is a struct (`RawNumFormat::ZERO`,
    // `DayPeriods::ENGLISH`) has no C spelling: cbindgen would write a compound literal
    // naming constants it never emits. No configuration leaves them out (`[export] exclude`
    // does not reach associated constants), hence the IR, behind cbindgen's `unstable_ir`
    // feature. A transparent struct's constant is its one field's value
    // (`NativeDigits_NONE`), and the integer constants stay: the flags and the layouts'
    // sizes are what a C caller builds a format from.
    for item in &mut bindings.items {
        if let ItemContainer::Struct(item) = item
            && !item.is_transparent
        {
            item.associated_constants
                .retain(|constant| !matches!(constant.value, Literal::Struct { .. }));
        }
    }
    let mut generated = Vec::new();
    bindings.write(&mut generated);
    for header in HEADERS.map(|path| crate_dir.join(path)) {
        if bless {
            std::fs::write(&header, &generated).unwrap();
            continue;
        }
        let committed = std::fs::read(&header).unwrap_or_default();
        assert!(
            committed == generated,
            "{} is not what cbindgen generates from src/; \
             run `HYPERCAST_BLESS=1 cargo test --test header` in rust/",
            header.display()
        );
    }
}
